SUBARRAY = "def subarray_sum(nums, k):\n    seen = {0: 1}\n    pref = ans = 0\n    for x in nums:\n        pref += x\n        ans += seen.get(pref - k, 0)\n        seen[pref] = seen.get(pref, 0) + 1\n    return ans\n"

